#!/usr/bin/env bash
# Start the locally built ARTEX binary against the bundled PostgreSQL container.
set -euo pipefail

cd "$(dirname "$0")/.."

[[ -x ./artex ]] || { echo "[artex] ./artex is missing; run ./scripts/setup-linux-vm.sh first" >&2; exit 1; }
[[ -f .env ]] || { echo "[artex] .env is missing; run ./scripts/setup-linux-vm.sh first" >&2; exit 1; }

# .env is generated by setup and contains only local values. Values written by
# the setup script are URL-safe, so sourcing it is safe here.
set -a
# shellcheck disable=SC1091
. ./.env
set +a

if [[ -z "${ARTEX_PG_HOST:-}" ]]; then
  CID="$(docker compose ps -q postgres 2>/dev/null || true)"
  if [[ -z "$CID" ]]; then
    echo "[artex] PostgreSQL is not running; starting it"
    docker compose up -d postgres
    CID="$(docker compose ps -q postgres)"
  fi
  ARTEX_PG_HOST="$(docker inspect -f '{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}' "$CID")"
  [[ -n "$ARTEX_PG_HOST" ]] || { echo "[artex] could not determine the PostgreSQL container IP" >&2; exit 1; }
fi

export ARTEX_PG_HOST
export ARTEX_PG_PORT="${ARTEX_PG_PORT:-5432}"
export ARTEX_PG_USER="${POSTGRES_USER:-artex}"
export ARTEX_PG_PASSWORD="${POSTGRES_PASSWORD:?POSTGRES_PASSWORD missing in .env}"
export ARTEX_PG_DBNAME="${POSTGRES_DB:-artex}"
export ARTEX_PG_SSLMODE="${ARTEX_PG_SSLMODE:-disable}"

echo "[artex] PostgreSQL: ${ARTEX_PG_USER}@${ARTEX_PG_HOST}:${ARTEX_PG_PORT}/${ARTEX_PG_DBNAME}"
echo "[artex] UI:         http://${ARTEX_BIND_ADDR:-0.0.0.0}:8787"
echo "[artex] setup token is printed on first start (also: grep \"Setup token\" artex.log)"
echo

exec ./artex \
  -addr "${ARTEX_ADDR:-${ARTEX_BIND_ADDR:-0.0.0.0}:8787}" \
  -proxy "${ARTEX_PROXY_ADDR:-127.0.0.1:8788}"
